param([string]$RepoRoot)
$ErrorActionPreference="Stop";Set-StrictMode -Version Latest;$Package=$PSScriptRoot;if([string]::IsNullOrWhiteSpace($RepoRoot)){$RepoRoot=Split-Path -Parent $Package};$RepoRoot=(Resolve-Path $RepoRoot).Path;$Payload=Join-Path $Package "Payload";if(-not(Test-Path (Join-Path $RepoRoot "WildsEngine.sln"))){throw "WildsEngine.sln not found."};if(@(git -C $RepoRoot status --short -- .\WildsEngine.Core).Count -gt 0){throw "Core has changes."};foreach($r in @("WildsEngine.Discoveries\Surface\WildsDiscoveries.cs","WildsEngine.Discoveries\Abstractions\Clusters\IDiscoveryClusterRecognitionResult.cs")){if(-not(Test-Path (Join-Path $RepoRoot $r))){throw "Required H4A foundation missing: $r"}};Get-ChildItem $Payload -Recurse -File|%{$rel=$_.FullName.Substring($Payload.Length).TrimStart('\','/');$dest=Join-Path $RepoRoot $rel;New-Item -ItemType Directory -Path (Split-Path -Parent $dest) -Force|Out-Null;Copy-Item $_.FullName $dest -Force;Write-Host "[INSTALL] $rel" -ForegroundColor Green};dotnet build (Join-Path $RepoRoot "WildsEngine.Core.Tests\WildsEngine.Core.Tests.csproj") -c Release;if($LASTEXITCODE -ne 0){throw "Release build failed."};if(@(git -C $RepoRoot status --short -- .\WildsEngine.Core).Count -gt 0){throw "Core changed."};Write-Host "H4A installed. Run .\WildsEngine.Core.Tests\Entities\Runners\Invoke-E7H4A.ps1" -ForegroundColor Green
